(function(){
 'use strict';
 const labels=['ru','en','de','uk'];

 const countForms={"current":{"ru":["текущая сессия","текущие сессии","текущих сессий"],"en":["current session","current sessions"],"de":["aktuelle Sitzung","aktuelle Sitzungen"],"uk":["поточна сесія","поточні сесії","поточних сесій"]},"history":{"ru":["запись истории","записи истории","записей истории"],"en":["history entry","history entries"],"de":["Verlaufseintrag","Verlaufseinträge"],"uk":["запис історії","записи історії","записів історії"]},"records":{"ru":["запись","записи","записей"],"en":["record","records"],"de":["Eintrag","Einträge"],"uk":["запис","записи","записів"]},"accounts":{"ru":["учётная запись","учётные записи","учётных записей"],"en":["account","accounts"],"de":["Benutzerkonto","Benutzerkonten"],"uk":["обліковий запис","облікові записи","облікових записів"]},"sessions":{"ru":["сессия","сессии","сессий"],"en":["session","sessions"],"de":["Sitzung","Sitzungen"],"uk":["сесія","сесії","сесій"]},"guestSessions":{"ru":["гостевая сессия UniFi","гостевые сессии UniFi","гостевых сессий UniFi"],"en":["UniFi guest session","UniFi guest sessions"],"de":["UniFi-Gäste-Sitzung","UniFi-Gäste-Sitzungen"],"uk":["гостьова сесія UniFi","гостьові сесії UniFi","гостьових сесій UniFi"]}};
 function count(kind,n){
  const forms=countForms[kind]?.[language];
  if(!forms)throw Error('Unknown count label: '+kind);
  const value=Math.max(0,Math.trunc(Number(n)||0));
  const digit=value%10, last2=value%100;
  const index=(language==='ru'||language==='uk')
   ?(last2>=11&&last2<=14?2:digit===1?0:digit>=2&&digit<=4?1:2)
   :(value===1?0:1);
  return value+' '+forms[index];
 }
 function actionCount(kind,n){
  if(kind!=='guestDisconnect')throw Error('Unknown action count: '+kind);
  const prefix={ru:'Отправить Disconnect · ',en:'Send Disconnect · ',de:'Disconnect senden · ',uk:'Надіслати Disconnect · '};
  return prefix[language]+count('guestSessions',n);
 }

 const dict=Object.create(null);
 for(const [ru,en,de,uk] of entries)dict[ru]={ru,en,de,uk};
 const tokens=Object.keys(dict).filter(k=>k.trim().length>=2).sort((a,b)=>b.length-a.length);
 const pageTitle=document.title;
 function escapeRx(s){return s.replace(/[-/\\^$*+?.()|[\]{}]/g,'\\$&');}
 const rx=new RegExp(tokens.map(escapeRx).join('|'),'g');
 const textOriginal=new WeakMap(),textDisplayed=new WeakMap(),attrOriginal=new WeakMap(),attrDisplayed=new WeakMap();
 const languageKey='bixcore-ui-language',themeKey='bixcore-ui-theme';
 function read(key){try{return localStorage.getItem(key);}catch{return null;}}
 function save(key,val){try{localStorage.setItem(key,val);}catch{}}
 let language=labels.includes(read(languageKey))?read(languageKey):'ru';
 let theme=['dark','light'].includes(read(themeKey))?read(themeKey):'dark';
 function translate(value){
  if(language==='ru'||typeof value!=='string')return value;
  const trimmed=value.trim();
  const normalized=trimmed.replace(/\s+/g,' ');
  if(dict[normalized])return value.replace(trimmed,dict[normalized][language]);
  return value.replace(rx,k=>dict[k][language]);
 }
 function renderText(node){
  if(!node||node.nodeType!==3||node.parentElement?.closest('script,style,[data-i18n-ignore]'))return;
  const value=node.nodeValue||'';
  if(value!==textDisplayed.get(node))textOriginal.set(node,value);
  const translated=translate(textOriginal.get(node)||'');
  textDisplayed.set(node,translated);
  if(value!==translated)node.nodeValue=translated;
 }
 const attributes=['title','placeholder','aria-label','data-label'];
 function renderAttrs(el){
  if(el.nodeType!==1||el.closest('[data-i18n-ignore]'))return;
  const prev=attrOriginal.get(el)||{},displayed=attrDisplayed.get(el)||{};
  for(const attr of attributes){
   if(!el.hasAttribute(attr))continue;
   const value=el.getAttribute(attr);
   if(value!==displayed[attr])prev[attr]=value;
   const translated=translate(prev[attr]||'');
   displayed[attr]=translated;
   if(value!==translated)el.setAttribute(attr,translated);
  }
  attrOriginal.set(el,prev);attrDisplayed.set(el,displayed);
 }
 function visit(root){
  if(root.nodeType===3){renderText(root);return;}
  if(root.nodeType!==1&&root.nodeType!==9)return;
  if(root.nodeType===1)renderAttrs(root);
  const walk=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);
  while(walk.nextNode()){
   const node=walk.currentNode;
   if(node.nodeType===3)renderText(node);else renderAttrs(node);
  }
 }
 let queued=false;
 function apply(){
  document.documentElement.lang=language;
  document.title=translate(pageTitle);
  document.documentElement.dataset.theme=theme;
  document.documentElement.style.colorScheme=theme;
  document.querySelectorAll('.bix-language').forEach(el=>{if(el.value!==language)el.value=language;});
  document.querySelectorAll('.bix-theme').forEach(el=>{
   const light=theme==='light';
   el.setAttribute('aria-pressed',String(light));
   el.setAttribute('title',light?'Тема: светлая':'Тема: тёмная');
   const icon=el.querySelector('.theme-icon');
   if(icon)icon.textContent=light?'☀':'☾';
  });
  visit(document.body);
 }
 document.addEventListener('change',event=>{
  if(event.target.matches('.bix-language')){
   language=event.target.value;save(languageKey,language);
   apply();window.dispatchEvent(new CustomEvent('bix:localechange',{detail:language}));
  }
 });
 document.addEventListener('click',event=>{
  if(event.target.closest('.bix-theme')){
   theme=theme==='dark'?'light':'dark';save(themeKey,theme);apply();
  }
 });
 const observer=new MutationObserver(changes=>{
  for(const m of changes){
   if(m.type==='childList'){for(const n of m.addedNodes)visit(n);}
   else if(m.type==='characterData')renderText(m.target);
   else if(m.type==='attributes')renderAttrs(m.target);
  }
 });
 observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attributes});
 window.BiXUI={get locale(){return language;},get theme(){return theme;},t:translate,count,actionCount,apply};
 apply();
})();
